"use client";

import { useState } from "react";
import { Mail, Phone, MapPin, Send, CheckCircle } from "lucide-react";
import { motion } from "@/common/components/motion";
import { Container } from "@/common/components/ui/container";
import { SectionHeading } from "@/common/components/ui/section-heading";
import { Button } from "@/common/components/ui/button";
import { FormField, FormTextarea } from "@/common/components/ui/form-field";
import { MotionStaggerGroup } from "@/common/components/motion";
import { fadeUp, staggerChild, viewportConfig } from "@/lib/animations";
import { CONTACT_INFO } from "@/common/constants/site";

const CONTACT_DETAILS = [
  {
    icon: Mail,
    label: "Email",
    value: CONTACT_INFO.email,
    href: `mailto:${CONTACT_INFO.email}`,
  },
  {
    icon: Phone,
    label: "Phone",
    value: CONTACT_INFO.phone,
    href: `tel:${CONTACT_INFO.phone.replace(/\s/g, "")}`,
  },
  {
    icon: MapPin,
    label: "Location",
    value: CONTACT_INFO.address,
    href: null,
  },
] as const;

export function ContactSection() {
  const [isSubmitted, setIsSubmitted] = useState(false);

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setIsSubmitted(true);
    setTimeout(() => setIsSubmitted(false), 4000);
  }

  return (
    <section id="contact" className="bg-background py-20 md:py-28" aria-label="Contact Us">
      <Container>
        <SectionHeading
          label="Contact"
          title="Get in Touch"
          description="Ready to start your next project or explore how Vyomnix can support your business? Reach out — we respond within one business day."
        />

        <div className="grid gap-12 lg:grid-cols-5">
          {/* Contact Info */}
          <MotionStaggerGroup className="space-y-6 lg:col-span-2">
            {CONTACT_DETAILS.map((detail) => {
              const Icon = detail.icon;
              const content = (
                <motion.div
                  key={detail.label}
                  variants={staggerChild}
                  className="flex items-start gap-4 rounded-xl border border-border bg-muted p-5 transition-shadow hover:shadow-sm"
                >
                  <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-secondary text-primary">
                    <Icon className="size-5" />
                  </div>
                  <div>
                    <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      {detail.label}
                    </p>
                    <p className="mt-1 text-sm font-medium text-accent">
                      {detail.value}
                    </p>
                  </div>
                </motion.div>
              );

              if (detail.href) {
                return (
                  <a key={detail.label} href={detail.href} className="block">
                    {content}
                  </a>
                );
              }
              return <div key={detail.label}>{content}</div>;
            })}

            {/* Support email */}
            <motion.div variants={staggerChild}>
              <p className="text-sm text-muted-foreground">
                For support enquiries:{" "}
                <a
                  href={`mailto:${CONTACT_INFO.support}`}
                  className="font-medium text-primary transition-colors hover:text-primary-hover"
                >
                  {CONTACT_INFO.support}
                </a>
              </p>
            </motion.div>
          </MotionStaggerGroup>

          {/* Contact Form */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={viewportConfig}
            className="lg:col-span-3"
          >
            <form
              onSubmit={handleSubmit}
              className="rounded-2xl border border-border bg-muted p-6 md:p-8"
            >
              <div className="grid gap-5 sm:grid-cols-2">
                <FormField
                  id="contact-name"
                  label="Full Name"
                  name="name"
                  required
                  placeholder="Your name"
                />
                <FormField
                  id="contact-email"
                  label="Email Address"
                  name="email"
                  type="email"
                  required
                  placeholder="you@company.com"
                />
              </div>

              <FormField
                id="contact-subject"
                label="Subject"
                name="subject"
                required
                placeholder="How can we help?"
                className="mt-5"
              />

              <FormTextarea
                id="contact-message"
                label="Message"
                name="message"
                required
                placeholder="Tell us about your project..."
                className="mt-5"
              />

              {/* Submit */}
              <div className="mt-6">
                {isSubmitted ? (
                  <div className="flex items-center gap-2 rounded-lg bg-primary/10 px-5 py-3 text-sm font-medium text-primary">
                    <CheckCircle className="size-4" />
                    Thank you! We&apos;ll get back to you soon.
                  </div>
                ) : (
                  <Button type="submit" size="lg" className="w-full sm:w-auto">
                    Send Message
                    <Send className="ml-1 size-4" />
                  </Button>
                )}
              </div>
            </form>
          </motion.div>
        </div>
      </Container>
    </section>
  );
}
