"use client";

import { motion } from "@/common/components/motion";
import { Badge } from "@/common/components/ui/badge";
import { staggerChild, scaleOnHover } from "@/lib/animations";
import { getIcon } from "@/lib/icons";
import type { Service } from "@/common/types";

interface ServiceCardProps {
  service: Service;
}

export function ServiceCard({ service }: ServiceCardProps) {
  const Icon = getIcon(service.icon);

  return (
    <motion.div
      variants={staggerChild}
      whileHover={scaleOnHover}
      className="group flex flex-col rounded-2xl border border-border bg-white p-8 transition-shadow hover:shadow-lg md:p-10"
    >
      {/* Icon */}
      <div className="mb-6 flex size-14 items-center justify-center rounded-xl bg-secondary text-primary transition-colors group-hover:bg-primary group-hover:text-white">
        {Icon && <Icon className="size-7" />}
      </div>

      {/* Content */}
      <h3 className="text-xl font-semibold text-accent">{service.title}</h3>
      <p className="mt-3 flex-1 leading-relaxed text-muted-foreground">
        {service.description}
      </p>

      {/* Tags */}
      <div className="mt-6 flex flex-wrap gap-2">
        {service.tags.map((tag) => (
          <Badge key={tag} variant="outline">
            {tag}
          </Badge>
        ))}
      </div>
    </motion.div>
  );
}
